const {chromium}=require('playwright'),{pathToFileURL}=require('url'),path=require('path'),fs=require('fs');
(async()=>{const b=await chromium.launch({args:['--no-sandbox']});try{const p=await b.newPage({viewport:{width:390,height:1000}}),errors=[];p.on('pageerror',e=>errors.push(e.message));await p.goto(process.env.ART_SITE_URL||pathToFileURL(path.resolve('index.html')).href);await p.click('#learningTab');
await p.evaluate(()=>{for(const [id,v] of Object.entries(DEUTSCH_KARL_CONVERSATION.phrases))if(id!=='karl'&&recordedAudioFiles(v[0])?.length!==1)throw Error('Missing whole audio '+v[0]);window.speak=()=>Promise.resolve();window.tone=()=>{};const j=DEUTSCH_JOURNEY;j.select(0);j.karlConversation();if(document.querySelector('[data-karl-conversation]'))throw Error('Wrong island access');j.select(1);j.karlConversation();if(document.querySelector('[data-karl-conversation]'))throw Error('Access without key');profileStorage.setItem(j.key,JSON.stringify({version:1,lessons:{0:{passed:true,best:100}},final:{passed:true,best:86}}));sessionStorage.setItem('karlProgress',profileStorage.getItem(j.key));sessionStorage.setItem('karlActivity',DEUTSCH_PROGRESS.snapshot().answers);j.map()});await p.click('#karlConversationOpen');await p.click('#karlBegin');fs.mkdirSync('audit-screenshots',{recursive:true});
for(let i=0;i<8;i++){if(await p.locator('[data-karl-turn]').getAttribute('data-karl-turn')!==String(i))throw Error('Turn order');for(const width of [320,390,1280]){await p.setViewportSize({width,height:1000});if(await p.evaluate(()=>document.documentElement.scrollWidth>innerWidth+1))throw Error('Overflow '+i+' '+width)}
if(i===0){await p.evaluate(()=>{const x=document.querySelector('[data-karl-answer="bye"]');x.click();x.click();if(DEUTSCH_PROGRESS.snapshot().answers!==Number(sessionStorage.getItem('karlActivity'))+1)throw Error('Duplicate wrong choice')});await p.click('.fox-hint summary')}
if([3,4,5].includes(i)){if(i===3){await p.click('[data-karl-tile="3"]');await p.click('#karlCheck');await p.evaluate(()=>{const n=DEUTSCH_PROGRESS.snapshot().answers;document.querySelector('#karlCheck').click();if(DEUTSCH_PROGRESS.snapshot().answers!==n)throw Error('Duplicate tile attempt')});await p.click('#karlClear')}const count=await p.evaluate(i=>DEUTSCH_KARL_CONVERSATION.turns[i].tiles.length-1,i);for(let k=0;k<count;k++)await p.click('[data-karl-tile="'+k+'"]');await p.click('#karlCheck')}else{const id=await p.evaluate(i=>DEUTSCH_KARL_CONVERSATION.turns[i].answer,i);await p.click('[data-karl-answer="'+id+'"]')}
await p.evaluate(()=>{const n=DEUTSCH_PROGRESS.snapshot().answers;document.querySelector('[data-karl-answer],#karlCheck').click();if(DEUTSCH_PROGRESS.snapshot().answers!==n)throw Error('Duplicate success')});if(i===3||i===5){await p.setViewportSize({width:390,height:1000});await p.locator('#learningView img').evaluateAll(xs=>Promise.all(xs.map(i=>i.decode())));await p.screenshot({path:'audit-screenshots/karl-turn-'+i+'.png',fullPage:true})}await p.click('#karlNext');if(!await p.evaluate(()=>document.querySelector('#karlBack').getBoundingClientRect().top>=document.querySelector('.mode-tabs').getBoundingClientRect().bottom-1))throw Error('Sticky nav hides conversation')}
if(!await p.evaluate(()=>DEUTSCH_KARL_CONVERSATION.read()?.completed&&DEUTSCH_KARL_CONVERSATION.read().completions===1&&document.querySelectorAll('.fox-finished-transcript .fox-speech').length===16&&profileStorage.getItem(DEUTSCH_JOURNEY.key)===sessionStorage.getItem('karlProgress')&&DEUTSCH_PROGRESS.snapshot().answers===Number(sessionStorage.getItem('karlActivity'))+10))throw Error('Completion/transcript/activity/reward retention');await p.screenshot({path:'audit-screenshots/karl-complete.png',fullPage:true});await p.click('#karlDone');if(await p.locator('.is-lighthouse-lit').count()!==1)throw Error('Light lost');await p.reload();await p.click('#learningTab');await p.click('#karlConversationOpen');await p.click('#karlBegin');await p.click('#karlBack');if(!await p.evaluate(()=>DEUTSCH_KARL_CONVERSATION.read()?.completed&&profileStorage.getItem(DEUTSCH_JOURNEY.key)===sessionStorage.getItem('karlProgress')))throw Error('Interrupted replay lost results');await p.evaluate(()=>{document.documentElement.lang='en';DEUTSCH_JOURNEY.karlConversation()});if(!(await p.locator('#learningView h1').textContent()).includes('Conversation with Karl'))throw Error('English missing');await p.click('#profileButton');await p.fill('#profileAddInput','Karl child');await Promise.all([p.waitForEvent('load'),p.click('#profileAddForm button')]);await p.click('#learningTab');if(await p.evaluate(()=>DEUTSCH_KARL_CONVERSATION.read()))throw Error('Profile leak');if(errors.length)throw Error(errors.join(';'));console.log('PASS Karl eight-exchange conversation, choices/tiles/distractors, hints/retries, exact activity, transcript, reward retention, replay/reload, localization and profile isolation');}finally{await b.close()}})().catch(e=>{console.error(e);process.exit(1)});
